import{_ as n,a0 as a,w as p,s as u,ao as l,I as o,a1 as s,A as i,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"在 Firefox 和 Chrome 中輕鬆截取完整網頁截圖 | LCTT x X-CMD","titleTemplate":false,"description":"在 Firefox 和 Chrome 中輕鬆截取完整網頁截圖 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Firefox 和 Chrome 中輕鬆截取完整網頁截圖 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Firefox 和 Chrome 中輕鬆截取完整網頁截圖 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230808 Easily Take Full Webpage Screenshots in Firefox and Chrome","title":"在 Firefox 和 Chrome 中輕鬆截取完整網頁截圖","tag":"202308","desc":""},"relativePath":"202308/20230808 Easily Take Full Webpage Screenshots in Firefox and Chrome.md","filePath":"[post].md"}'),f={name:"202308/20230808 Easily Take Full Webpage Screenshots in Firefox and Chrome.md"};function m(d,e,h,b,x,g){const r=a("Link");return p(),u("div",null,[e[21]||(e[21]=l('<h1 id="在-firefox-和-chrome-中輕鬆截取完整網頁截圖" tabindex="-1">在 Firefox 和 Chrome 中輕鬆截取完整網頁截圖 <a class="header-anchor" href="#在-firefox-和-chrome-中輕鬆截取完整網頁截圖" aria-label="Permalink to “在 Firefox 和 Chrome 中輕鬆截取完整網頁截圖”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202308/30/132752rfrq7af9sqraz76r.jpg" alt=""></p><blockquote><p>Firefox 瀏覽器內置了截屏工具，你可以用它對整個網頁進行截屏。Chrome 瀏覽器也有同樣的功能。</p></blockquote><p>截屏來捕獲信息是很常見的。</p><p>但你知道你可以在 Firefox 中截取整個網頁的截圖嗎？Firefox 附帶一個內置的截圖工具，允許你截取選定區域、可見屏幕區域甚至整個網頁的截圖。</p><p>這意味着如果你想保存網頁供以後參考，你可以快速捕獲整個網頁。</p><p>Chrome 也有截圖功能，但稍微複雜一些。</p><p>在本教程中，我將引導你完成以下內容：</p><ul><li>如何在 Firefox 中截圖</li><li>如何在 Chrome 中截圖</li><li>使用 Nimbus 擴展獲得比內置的截屏更多的功能</li></ul><p>那麼讓我們從第一個開始。</p><h3 id="在-firefox-中截取網頁截圖" tabindex="-1">在 Firefox 中截取網頁截圖 <a class="header-anchor" href="#在-firefox-中截取網頁截圖" aria-label="Permalink to “在 Firefox 中截取網頁截圖”">​</a></h3><p>Firefox 的內置工具可讓你通過單擊選擇整個屏幕、整個頁面，甚至特定段落。</p><h4 id="步驟-1-訪問截圖工具" tabindex="-1">步驟 1：訪問截圖工具 <a class="header-anchor" href="#步驟-1-訪問截圖工具" aria-label="Permalink to “步驟 1：訪問截圖工具”">​</a></h4><p>要啓動截圖程序，請在使用 Firefox 時按 <code>Ctrl + Shift + s</code>。</p><p>如果你不總是能記住快捷方式，也可以從右鍵單擊菜單訪問該工具。</p><p><img src="https://itsfoss.com/content/images/2023/08/take-screenshot-firefox.png" alt="Screenshot tool can also be accessed from right-click context menu"></p><p>如果你經常截圖，那麼將該程序添加到工具欄將是一個好主意。為此，你只需執行三個簡單步驟：</p><ol><li>首先，右鍵單擊工具欄並選擇 “<ruby>自定義工具欄<rt>Customize Toolbar</rt></ruby>” 選項</li><li>找到 “<ruby>截圖<rt>Screenshot</rt></ruby>” 程序並將其拖至工具欄</li><li>點擊 “<ruby>完成<rt>Done</rt></ruby>” 按鈕即可</li></ol><p>還困惑嗎？ 操作方法如下：</p><p><img src="https://itsfoss.com/content/images/2023/08/Add-screenshot-feature-to-Firefox-browser-1.gif" alt=""></p><p>啓用後，你可以單擊剛剛拖動到工具欄的截圖圖標。</p><h4 id="步驟-2-在-firefox-中截圖" tabindex="-1">步驟 2：在 Firefox 中截圖 <a class="header-anchor" href="#步驟-2-在-firefox-中截圖" aria-label="Permalink to “步驟 2：在 Firefox 中截圖”">​</a></h4><p>當你啓動截圖工具時，它會提示兩個選項：“<ruby>保存整頁<rt>Save full page</rt></ruby>” 和 “<ruby>保存可見<rt>Save visible</rt></ruby>”。這裏：</p><ul><li>保存整頁將捕獲整個網頁</li><li>保存可見只會捕獲當前幀中可見的內容</li></ul><p>但如果你想捕獲特定部分，你可以使用鼠標光標選擇該部分並保存：</p><p><img src="https://itsfoss.com/content/images/2023/08/Capture-specific-part-of-webpage-to-screenshot-in-Firefox.gif" alt=""></p><p>如你所見，有兩個選項：<ruby>下載<rt>Download</rt></ruby> 或 <ruby>複製<rt>Copy</rt></ruby>（到剪貼板，以便你可以將其粘貼到文檔或編輯工具中）。你可以根據你的場景使用其中之一。</p><h3 id="在-chrome-中截取網頁截圖" tabindex="-1">在 Chrome 中截取網頁截圖 <a class="header-anchor" href="#在-chrome-中截取網頁截圖" aria-label="Permalink to “在 Chrome 中截取網頁截圖”">​</a></h3><p>在 Chrome 中截取全部網頁截圖比在 Firefox 中要複雜一些，因為它隱藏在開發人員選項下。</p><p>不用擔心！你將通過以下步驟做到：</p><ul><li>打開菜單，進入 “<ruby>更多工具<rt>More Tools</rt></ruby>-&gt;<ruby>開發者工具<rt>Developer tools</rt></ruby>”。或者，你可以按 <code>Ctrl + Shift + l</code> 進入開發者工具目錄。</li><li>按 <code>Ctrl + Shift + p</code> 並輸入 <code>screenshot</code>（LCTT 譯註：在中文環境中請輸入 “屏幕截圖”）</li><li>選擇區域或整個頁面，然後回下載截圖。</li></ul><p>讓我向你展示如何做到這一點：</p><p><img src="https://itsfoss.com/content/images/2023/08/Take-screenshots-in-Google-chrome-without-any-extension-2-.gif" alt=""></p><p>這幾乎就是 Chrome 所能提供的一切。</p><h3 id="如何使用擴展程序截圖" tabindex="-1">如何使用擴展程序截圖 <a class="header-anchor" href="#如何使用擴展程序截圖" aria-label="Permalink to “如何使用擴展程序截圖”">​</a></h3><blockquote><p>✋ 非自由和開源軟件警告！這裏討論的 Nimbus 擴展不是開源的。</p></blockquote><p>如果你想要更多功能，例如添加延遲、水印或符號，那麼你必須使用擴展程序。</p><p>為此，我建議使用 Nimbus，它幾乎可以讓你執行任何本地安裝的截圖工具可以執行的所有操作。</p><p>下載 Firefox 版 Nimbus：</p>',39)),o("blockquote",null,[o("p",null,[o("strong",null,[s(r,{href:"https://addons.mozilla.org/en-US/firefox/addon/nimbus-screenshot/?utm_source=addons.mozilla.org&utm_medium=referral&utm_content=search"},{default:i(()=>[...e[0]||(e[0]=[t("Firefox 版 Nimbus",-1)])]),_:1})])])]),e[22]||(e[22]=o("p",null,"下載 Chrome 版 Nimbus：",-1)),o("blockquote",null,[o("p",null,[o("strong",null,[s(r,{href:"https://chrome.google.com/webstore/detail/nimbus-screenshot-screen/bpconcjcammlapcogcnnelfmaeghhagj"},{default:i(()=>[...e[1]||(e[1]=[t("Chrome 版 Nimbus",-1)])]),_:1})])])]),e[23]||(e[23]=l('<blockquote><p>📋 只有 Nimbus 的 Chrome 擴展具有視頻錄製功能。</p></blockquote><p>完成安裝後，<strong>請務必註冊 Nimbus 以啓用所有功能。</strong></p><p>單擊 Nimbus 擴展圖標，你會看到多個選項：</p><p><img src="https://itsfoss.com/content/images/2023/08/Use-nimbus-extension-to-take-full-screen-screenshots-in-chrome-and-firefox.png" alt=""></p><p>你可以選擇任何顯示的功能，完成後，根據捕獲後進行的操作（我選擇編輯），它將直接下載截圖，打開編輯器或將其發送到任何選定的雲提供商。</p><p>如果你也將 “<ruby>編輯<rt>Edit</rt></ruby>” 作為捕獲後的操作，那麼它將打開一個編輯器，你可以在其中對捕獲的截圖進行編輯：</p><p><img src="https://itsfoss.com/content/images/2023/08/Edit-screenshots-captured-in-Firefox-and-Chrome.png" alt=""></p><p>如果你想添加水印、瞭解/更改快捷方式、更改截圖的格式等，請打開 Nimbus 並點擊小齒輪按鈕：</p><p><img src="https://itsfoss.com/content/images/2023/08/Additional-settings-of-Nimbus.png" alt=""></p><p>只是一個擴展卻有非常酷的功能。不是嗎？</p><blockquote><p>💡 如果你經常截屏，你可能需要將 Nimbus 擴展固定到任務欄。</p></blockquote><h3 id="想要更多功能嗎-使用截圖工具" tabindex="-1">想要更多功能嗎？使用截圖工具 <a class="header-anchor" href="#想要更多功能嗎-使用截圖工具" aria-label="Permalink to “想要更多功能嗎？使用截圖工具”">​</a></h3><p>如果你不想受到擴展功能的束縛，那麼需要嘗試具有更多功能的截圖工具，這些工具可以在整個系統的任何地方使用。</p>',13)),o("p",null,[e[3]||(e[3]=t("如果你是 Linux 用户，那麼我們有一份關於 ",-1)),s(r,{href:"https://itsfoss.com/take-screenshot-linux/"},{default:i(()=>[...e[2]||(e[2]=[t("Linux 中截取和編輯截圖的最佳工具",-1)])]),_:1}),e[4]||(e[4]=t(" 的專門指南：",-1))]),o("blockquote",null,[o("p",null,[o("strong",null,[s(r,{href:"https://itsfoss.com/take-screenshot-linux/"},{default:i(()=>[...e[5]||(e[5]=[t("Linux 中截取和編輯截圖的最佳工具",-1)])]),_:1})])])]),e[24]||(e[24]=o("p",null,"我希望你喜歡這個快速技巧。",-1)),e[25]||(e[25]=o("p",null,"（題圖：MJ/76cc0d02-fb37-4bd0-94ec-fc249c1f537e）",-1)),e[26]||(e[26]=o("hr",null,null,-1)),o("p",null,[e[7]||(e[7]=t("via: ",-1)),s(r,{href:"https://itsfoss.com/firefox-screenshot/"},{default:i(()=>[...e[6]||(e[6]=[t("https://itsfoss.com/firefox-screenshot/",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("作者：",-1)),s(r,{href:"https://itsfoss.com/author/sagar/"},{default:i(()=>[...e[8]||(e[8]=[t("Sagar Sharma",-1)])]),_:1}),e[13]||(e[13]=t(" 選題：",-1)),s(r,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),s(r,{href:"https://github.com/geekpi"},{default:i(()=>[...e[10]||(e[10]=[t("geekpi",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),s(r,{href:"https://github.com/wxy"},{default:i(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[18]||(e[18]=t("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創編譯，",-1)),s(r,{href:"https://linux.cn/"},{default:i(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const k=n(f,[["render",m]]);export{c as __pageData,k as default};
